    // "x" * 12 -> "Cx"      (counts > 9 use uppercase hex: A=10, B=11, ...)
    // Single chars still get count prefix: "a" -> "1a"

    // Run-length encode: count-first format, hex digits for counts > 9.
    // Maximum run length per group: 15 (F in hex). Longer runs split.
    static string RleEncode(string input) {

