    // - 'export ' prefix on a line is stripped before parsing.
    // - '#' comments outside double quotes (use StripComment).
    // - Lines ending '\' continue (leading space trimmed).
    // - Double-quoted values unquoted; single-quoted values kept WITH quotes.
    static Dictionary<string, string> ParseEnvFile(string text)
    {
