    // Run-length encode a string. Custom format rules:
    // - Single chars are output as-is (NOT "1a" or "a1")
    // - Runs of 2+ are output as COUNT THEN CHAR (e.g., "aaa" -> "3a")
    // - Digits in input are escaped by prefixing with '\' (e.g., "3" -> "\3")
    // - Backslash in input is escaped as "\\"
    // NOTE: runs of digits are ALSO escaped per-char, e.g., "222" -> "3\2"
    static string RunLengthEncode(string input)
    {

golden_completion:
