using System;
using System.Collections.Generic;

class Program
{
    // Split a string by a delimiter, but ignore delimiters inside brackets.
    // Bracket pairs: (), [], {}
    // Also ignore delimiters inside double-quoted strings (handle \" escape)
    // Delimiter defaults to ','
    // Trim each resulting segment.
    static List<string> BracketAwareSplit(string input, char delimiter = ',')
    {

golden_completion:
var result = new List<string>();
int depth = 0;
bool inString = false;
bool escaped = false;
int start = 0;
for (int i = 0; i < input.Length; i++)
{
    char c = input[i];
    if (escaped) { escaped = false; continue; }
    if (c == '\\' && inString) { escaped = true; continue; }
    if (c == '"') { inString = !inString; continue; }
    if (inString) continue;
    if (c == '(' || c == '[' || c == '{') depth++;
    else if (c == ')' || c == ']' || c == '}') depth--;
    else if (c == delimiter && depth == 0)
    {
        result.Add(input.Substring(start, i - start).Trim());
        start = i + 1;
    }
}
result.Add(input.Substring(start).Trim());
return result;

