class Program
{
    // Analyzes a method and returns a precise description string.
    // The description MUST contain ALL of the following keywords based on method properties:
    // - "mutates" if the method modifies a collection parameter (add/remove/set)
    // - "pure" if the method has no side effects (only reads, returns value)
    // - "throws" if the method can throw an exception
    // - "nullable" if the method can return null
    // - "O(n)" or "O(n^2)" etc for time complexity
    // - "allocates" if the method creates new collections/objects
    // Description format: "keyword1, keyword2, keyword3" (sorted alphabetically)
    static string DescribeMethod(string methodName, string code)
    {

