        if (lower.Substring(j, kw.Length) == kw) loops++;
if (loops >= 2) keywords.Add("O(n^2)");
else if (loops >= 1) keywords.Add("O(n)");
else keywords.Add("O(1)");
if (!keywords.Contains("mutates") && !keywords.Contains("throws"))
    keywords.Add("pure");
return string.Join(", ", keywords);

